import { Organizations, useGetOrganizations } from './useGetOrganizations'
import { useOrganizationStore } from '@/stores/organizationStore'

export function useCurrentOrganization(): {
	currentOrganization: Organizations['edges'][number]['node'] | null
	loading: boolean
} {
	const { organizations, loading } = useGetOrganizations()
	const { currentOrganizationIndex } = useOrganizationStore()
	const currentOrganization =
		organizations?.edges[currentOrganizationIndex]?.node ?? null
	if (loading && !currentOrganization) {
		return { currentOrganization: null, loading: true }
	}
	return { currentOrganization, loading: false }
}
